import sys
from math import sqrt
from itertools import combinations

def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    limit = int(sqrt(num)) + 1
    for i in range(3, limit, 2):
        if num % i == 0:
            return False
    return True

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    k = int(next(iterator))

    cards = []
    for _ in range(n):
        p = int(next(iterator))
        c = int(next(iterator))
        l = int(next(iterator))
        cards.append((p, c, l))

    levels = sorted(list(set(c[2] for c in cards)))

    def can_achieve(level):
        available = [i for i, (_, _, l) in enumerate(cards) if l <= level]
        m = len(available)
        if m == 0:
            return False

        adj = [[False] * m for _ in range(m)]
        for i in range(m):
            for j in range(i + 1, m):
                c_i = cards[available[i]][1]
                c_j = cards[available[j]][1]
                if is_prime(c_i + c_j):
                    adj[i][j] = adj[j][i] = True

        dp = [-1] * (m + 1)
        dp[0] = 0

        for i in range(m):
            new_dp = dp[:]
            p_i = cards[available[i]][0]
            for j in range(i + 1):
                if dp[j] != -1:
                    conflict = False
                    for t in range(j):
                        if adj[available[t]][available[i]]:
                            conflict = True
                            break
                    if not conflict:
                        if new_dp[j + 1] < dp[j] + p_i:
                            new_dp[j + 1] = dp[j] + p_i
            dp = new_dp

        max_power = max(dp)
        return max_power >= k

    ans = -1
    for level in levels:
        if can_achieve(level):
            ans = level
            break

    if ans == -1:
        print("-1")
    else:
        print(ans)

solve()
